use super::*;

/// Step by CALENDAR months, keeping the day of the month and clamping where it does not exist.
///
/// `2026-01-31` plus one month is `2026-02-28`, not `2026-03-03`. Plus TWO months is `2026-03-31`,
/// not `2026-03-28` — the anchor is the ORIGINAL date, so a bill on the 31st does not walk backwards
/// through the year every time it passes a short month.
pub fn add_calendar_months(iso: &str, n: i64) -> String {
    let (y, m, d) = match (iso.get(0..4).and_then(|s| s.parse::<i64>().ok()), iso.get(5..7).and_then(|s| s.parse::<i64>().ok()), iso.get(8..10).and_then(|s| s.parse::<i64>().ok())) {
        (Some(y), Some(m), Some(d)) => (y, m, d),
        _ => return iso.to_string(),
    };
    let total = y * 12 + (m - 1) + n;
    let mm = total.rem_euclid(12);
    let yy = (total - mm) / 12;
    format!("{yy:04}-{:02}-{:02}", mm + 1, d.min(days_in_month(yy, mm + 1)))
}
